import React from 'react';
import { Suspense, useEffect, useRef, useState } from 'react';
import { MapViewer, type MapViewerProps } from '@eyeon/map/viewer';
import '@eyeon/map/viewer/index.css';
import './wp.css';

function App() {
  const appRef = useRef<HTMLDivElement>(null);
  const [args, setArgs] = useState<MapViewerProps | null>(null);

  useEffect(() => {
    if (!appRef.current) return;
    const parent = appRef.current.parentElement as HTMLDivElement | null;
    if (!parent) return;

    const applyProps = (props: MapViewerProps) => {
      setArgs({ ...props });
    };

    const appProps = (parent as any).eyeonMapProps as MapViewerProps | undefined;
    if (appProps) {
      applyProps(appProps);
      return;
    }

    const handlePropsReady = (e: Event) => {
      const detail = (e as CustomEvent).detail;
      if (detail?.props) applyProps(detail.props);
      parent.removeEventListener('eyeon:map:props:ready', handlePropsReady);
    };
    parent.addEventListener('eyeon:map:props:ready', handlePropsReady);
    return () => {
      parent.removeEventListener('eyeon:map:props:ready', handlePropsReady);
    };
  }, []);

  return (
    <div className="App" ref={appRef}>
      <Suspense fallback={<div className="messageStyle">Map loading, please wait...</div>}>
        {args && (
          <MapViewer {...args} style={{ width: '100%', height: '100%', ...args.style }} />
        )}
      </Suspense>
    </div>
  );
}

export default App;
